CREATE TABLE IF NOT EXISTS kri_data_points (
  data_point_id       UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  kri_id              UUID NOT NULL REFERENCES risk_kris(kri_id) ON DELETE CASCADE,
  value               NUMERIC(10,2) NOT NULL,
